package cl.bolsillo.app;
import android.animation.*;import android.view.*;import android.view.animation.PathInterpolator;
/** Animate a bounded viewport once, on its hardware layer; never fade a whole long ledger. */
final class PageMotion {
 static final android.view.animation.Interpolator EASE=new PathInterpolator(.2f,0f,0f,1f);
 static final java.util.WeakHashMap<View,ViewTreeObserver.OnPreDrawListener> pending=new java.util.WeakHashMap<>();
 static final java.util.WeakHashMap<View,ValueAnimator> animations=new java.util.WeakHashMap<>();
 static View viewport(View content){return content.getParent() instanceof android.widget.ScrollView?(View)content.getParent():content;}
 static boolean running(View source){if(animations.containsKey(source))return true;if(source instanceof android.view.ViewGroup){ViewGroup group=(ViewGroup)source;if(group.getChildCount()>0)return animations.containsKey(group.getChildAt(0));}return false;}
 static void reset(View view){ViewTreeObserver.OnPreDrawListener old=pending.remove(view);if(old!=null&&view.getViewTreeObserver().isAlive())view.getViewTreeObserver().removeOnPreDrawListener(old);ValueAnimator animation=animations.remove(view);if(animation!=null){animation.removeAllUpdateListeners();animation.cancel();}View window=viewport(view);window.setLayerType(View.LAYER_TYPE_NONE,null);window.setTranslationX(0);view.animate().withEndAction(null).cancel();view.setTranslationX(0);view.setTranslationY(0);view.setAlpha(1);}
 static void animate(View key,View target,float from,int duration){View window=viewport(key);window.setLayerType(View.LAYER_TYPE_HARDWARE,null);target.setTranslationX(from);ValueAnimator animation=ValueAnimator.ofFloat(from,0);animations.put(key,animation);animation.setDuration(duration);animation.setInterpolator(EASE);animation.addUpdateListener(v->target.setTranslationX((Float)v.getAnimatedValue()));animation.addListener(new AnimatorListenerAdapter(){@Override public void onAnimationEnd(Animator a){if(animations.get(key)==a){animations.remove(key);target.setTranslationX(0);window.setLayerType(View.LAYER_TYPE_NONE,null);}}});animation.start();}
 static void enter(View view,int direction){reset(view);if(!ValueAnimator.areAnimatorsEnabled())return;final ViewTreeObserver.OnPreDrawListener[] listener=new ViewTreeObserver.OnPreDrawListener[1];listener[0]=()->{if(view.getViewTreeObserver().isAlive())view.getViewTreeObserver().removeOnPreDrawListener(listener[0]);if(pending.get(view)!=listener[0])return true;pending.remove(view);if(view.isAttachedToWindow())animate(view,viewport(view),Glass.dp(view.getContext(),direction*14),180);return true;};pending.put(view,listener[0]);view.getViewTreeObserver().addOnPreDrawListener(listener[0]);view.addOnAttachStateChangeListener(new View.OnAttachStateChangeListener(){public void onViewAttachedToWindow(View v){}public void onViewDetachedFromWindow(View v){reset(v);v.removeOnAttachStateChangeListener(this);}});}
 static void settle(View view){float from=view.getTranslationX();reset(view);if(ValueAnimator.areAnimatorsEnabled()&&from!=0)animate(view,view,from,150);}
}
